def years_of(dur):
    m = re.match(r"\s*([\d.]+)", dur.translate(_PD))
    return float(m.group(1)) if m else 2.0


def prog_costs(p):
    """(tuition total, living total, grand total) for one catalogue row — numbers in the display currency."""
    dur, fee_num, city_key = p[5], p[7], p[2]
    yrs = years_of(dur)
    cur, lo, hi = fee_num
    r = rate(cur)
    t_lo, t_hi = lo * r * yrs, (hi if hi else lo) * r * yrs
    liv = first_amount(CITIES[city_key][1]) or (0, 0)
    l_lo, l_hi = liv[0] * 12 * yrs, liv[1] * 12 * yrs
    return (t_lo, t_hi), (l_lo, l_hi), (t_lo + l_lo, t_hi + l_hi)


