def fa(x, d=0):
    t = f"{x:.{d}f}"
    if d:
        t = t.rstrip("0").rstrip(".")
    return t.translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))


def amt(x):
    return money(x) if x < 10000 else money_k(x)


def budget_fit(p, sch=0, force=None, caveat=""):
    """$40k = tuition + n months of living; afterwards student work at the legal maximum. Returns numbers + the two cell texts."""
    (t_lo, t_hi), _, total = prog_costs(p)
    T = t_hi - sch
    lo, hi = first_amount(CITIES[p[2]][1])
    L = (lo + hi) / 2
    M = int(years_of(p[5]) * 12 + 0.5)
    w = WORK[p[0]]
    wage, wnote = WAGE_BY_CITY.get(p[2], (w["wage"], w["wage_note"]))
    W = w["hours"] * 4.33 * wage * rate(w["cur"]) * w["net"]      # net income per month at the legal maximum, display currency
    R = BUDGET - T
    n = max(0.0, R / L)
    covered = min(n, M)
    start = max(int(covered) + 1, w["start"])                     # first month that has to be paid from work
    work_months = max(0, M - (start - 1))
    left = R - (start - 1) * L                                    # budget left when work starts (negative = uncovered months before work is legal)
    gap = max(0.0, L - W)
    need = work_months * gap
    deficit = max(0.0, need - left)
    spare = max(0.0, left - need)
    if R <= 0:
        em = "❌"
    elif force:
        em = force
    elif deficit <= 1000:
        em = "✅" if (covered >= min(6, M) or work_months == 0) else "⚠️"   # fits, but less than 6 months of buffer
    elif deficit <= w["vac"] * M / 12 + 1000:
        em = "⚠️"                                                           # only full-time work in the breaks (legal) closes it
    else:
        em = "❌"
    # ---- step 1: tuition + one year of proof of funds ----
    pr = PROOF[p[0]]
    p_amount, p_note = PROOF_BY_CITY.get(p[2], (pr["amount"], pr["note"]))
    P = p_amount * rate(pr["cur"])
    gate = T + P
    gate_gap = gate - BUDGET
    if gate_gap <= 0:
        gem = "✅"
    elif gate_gap <= 3000 and pr["third_party"]:
        gem = "⚠️"
    else:
        gem = "❌"
    if P == 0:
        gate_txt = f"{gem} شهریه {money(T)} + تمکن $0 ({p_note}) = {money(gate)} ≤ $40,000 — ولی پول واقعی زندگی را ستون بعد نشان می‌دهد"
    elif gate_gap <= 0:
        gate_txt = f"{gem} شهریه {money(T)} + تمکن یک‌سال {money(P)} = {money(gate)} ≤ $40,000 ({money(-gate_gap)} زیر سقف) — {p_note}"
    else:
        gate_txt = f"{gem} شهریه {money(T)} + تمکن یک‌سال {money(P)} = {money(gate)} → {money(gate_gap)} بیشتر از $40,000"
        gate_txt += "؛ فقط اگر خانواده همین مبلغ را ۲۸ روز در حساب نشان دهد" if gem == "⚠️" else ""
        gate_txt += f" — {p_note}"
    sym = _CUR_SYM[w["cur"]]
    wage_s = f"{sym}{wage:.2f}".rstrip("0").rstrip(".") if wage < 100 else f"{sym}{wage:,.0f}"
    base = f"{fa(w['hours'])} ساعت/هفته × {wage_s} ({wnote}) ≈ {money(W)} خالص/ماه"
    if R <= 0:
        months_txt = f"{em} شهریه {money(T)} به‌تنهایی {money_k(-R)} بیشتر از $40,000 است → صفر ماه زندگی"
        work_txt = f"{em} کار جبران نمی‌کند — کسری قبل از اولین ماه زندگی شروع می‌شود ({base})"
    elif work_months == 0:
        months_txt = f"{em} شهریه {money(T)} + تمام {fa(M)} ماه زندگی ({money(L)}/ماه) — و {amt(spare)} اضافه می‌ماند"
        work_txt = f"{em} نیازی به کار نیست؛ اگر کار کنید ({base}) همه پس‌انداز می‌شود"
    else:
        months_txt = f"{em} شهریه {money(T)} + {fa(n, 1)} ماه زندگی ({money(L)}/ماه) از {fa(M)} ماه"
        if start - 1 > covered + 0.05:
            months_txt += f" — کار قانوناً از ماه {fa(start)} ({fa(start - 1 - covered, 1)} ماه بدون پوشش)"
        else:
            months_txt += f" → از ماه {fa(start)} باید کار کنید"
        if gap > 0:
            work_txt = f"{em} {base} در برابر زندگی {money(L)} → کسری {money(gap)}/ماه × {fa(work_months)} ماه = {amt(need)}"
            if left > 0:
                work_txt += f"؛ باقی‌ماندهٔ بودجه {money(left)}"
            elif left < 0:
                work_txt += f"؛ {money(-left)} ماه‌های بدون پوشش"
            work_txt += f" → کسری کل ≈ {amt(deficit)}" if deficit > 0 else f" → بدون کسری (≈ {money(spare)} اضافه)"
        else:
            work_txt = f"{em} {base} ≥ زندگی {money(L)} → از ماه {fa(start)} کسری صفر"
            if left > 0:
                work_txt += f" و {money(left)} از بودجه می‌ماند"
        if deficit > 0:
            work_txt += f"؛ قانوناً: {w['extra']}"
    if caveat:
        work_txt += f"؛ ⚠️ {caveat}"
    # overall verdict = worst of step 1 and step 2
    order = {"✅": 0, "⚠️": 1, "❌": 2}
    em_all = max((gem, em), key=lambda e: order[e])
    return dict(T=T, L=L, M=M, R=R, n=n, covered=covered, start=start, W=W, wage=wage, gap=gap, work_months=work_months,
                need=need, left=left, deficit=deficit, spare=spare, em=em, total=total, months_txt=months_txt, work_txt=work_txt,
                P=P, gate=gate, gate_gap=gate_gap, gem=gem, gate_txt=gate_txt, em_all=em_all)


